export const roomDefaults={width:5000,depth:4000,height:2800,wall:'#e8e5dd',floor:'oak',wallMaterial:'plaster',leftWall:'#e8e5dd',wallRoughness:.85,wallScale:1,wallThickness:100,floorColor:'#ffffff',floorRoughness:.55,floorScale:1,floorRotation:0,skirtingHeight:80,skirtingColor:'#eeeae0',backsplash:'none',backsplashHeight:600,backsplashColor:'#f0ede3',window:false,windowWidth:1400,windowHeight:1100,windowSill:1200,windowX:500,door:false,doorWidth:800,doorHeight:2100,doorZ:700,doorOpen:0,windowOpen:0,exposure:1,sun:2.6,lighting:'studio',environmentRotation:0,environmentIntensity:.85,floorProfile:'',wallProfile:'',backsplashProfile:''};
const clamp=(v,min,max,def)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):def;
export function normalizeRoom(raw){const r={...roomDefaults};for(const k of Object.keys(r))if(raw[k]!==undefined)r[k]=raw[k];for(const [k,min,max] of [['width',1500,12000],['depth',1500,12000],['height',1800,4500],['wallRoughness',.05,1],['floorRoughness',.05,1],['wallScale',.2,5],['floorScale',.2,5],['floorRotation',0,180],['wallThickness',50,400],['skirtingHeight',0,200],['backsplashHeight',200,1400],['exposure',.3,2],['sun',0,6],['environmentRotation',0,360],['environmentIntensity',0,2],['doorOpen',0,100],['windowOpen',0,100]])r[k]=clamp(r[k],min,max,roomDefaults[k]);for(const k of ['wall','leftWall','floorColor','skirtingColor','backsplashColor'])if(!/^#[a-f0-9]{6}$/i.test(r[k]))r[k]=roomDefaults[k];for(const k of ['window','door'])r[k]=!!r[k];r.windowSill=clamp(r.windowSill,200,r.height-400,1000);r.windowHeight=clamp(r.windowHeight,200,r.height-r.windowSill-100,700);r.windowWidth=clamp(r.windowWidth,300,r.width-200,1200);r.windowX=clamp(r.windowX,-r.width/2+r.windowWidth/2+100,r.width/2-r.windowWidth/2-100,0);r.doorWidth=clamp(r.doorWidth,500,r.depth-200,800);r.doorHeight=clamp(r.doorHeight,1500,r.height-100,2100);r.doorZ=clamp(r.doorZ,-r.depth/2+r.doorWidth/2+100,r.depth/2-r.doorWidth/2-100,0);if(!['oak','walnut','concrete','tile','marble'].includes(r.floor))r.floor='oak';if(!['plaster','paint','concrete','oak','marble'].includes(r.wallMaterial))r.wallMaterial='plaster';if(!['none','marble','tile','oak','concrete','paint'].includes(r.backsplash))r.backsplash='none';if(!['studio','daylight','warm'].includes(r.lighting))r.lighting='studio';for(const k of ['floorProfile','wallProfile','backsplashProfile'])if(!materialExists(r[k]))r[k]='';return {...r,...normalizeRoomExtensions({...raw,...r})};}
export function cleanDetails(raw){const result={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return result;for(const [id,d] of Object.entries(raw).slice(0,160)){if(!/^[a-z][a-z0-9-]{0,60}$/.test(id)||!d||typeof d!=='object')continue;const out={};for(const [k,min,max] of [['x',-3000,3000],['y',-3000,3000],['z',-3000,3000],['width',2,3000],['height',2,3000],['depth',2,3000],['rotation',-360,360],['open',0,100],['roughness',.05,1],['textureScale',.1,5],['grain',0,180],['handleLength',32,800],['handleSpacing',32,640],['mountHeight',10,2900],['hingeCupOffset',20.5,30],['edgeThickness',0,3],['textureOffsetX',-5000,5000],['textureOffsetY',-5000,5000]])if(typeof d[k]==='number'&&Number.isFinite(d[k])&&d[k]>=min&&d[k]<=max)out[k]=d[k];for(const k of ['color'])if(/^#[a-f0-9]{6}$/i.test(d[k]))out[k]=d[k];for(const [k,values] of [['finish',['inherit','paint','oak','walnut','marble','concrete','metal','glass']],['mechanism',['inherit','hinge','lift','slide','drop']],['handle',['inherit','bar','knob','profile','none','rail','cup']],['hinge',['standard','soft-close','wide-angle']],['handleOrientation',['horizontal','vertical']],['mountSide',['left','center','right']],['style',['inherit','flat','frame','slat','glass']]])if(values.includes(d[k]))out[k]=d[k];for(const k of ['material','edgeMaterial'])if(materialExists(d[k]))out[k]=d[k];if(typeof d.visible==='boolean')out.visible=d.visible;result[id]=out;}return result;}
export const MECHANISMS={hinge:'Распашной фасад · петли',lift:'Откидной вверх · подъёмник',slide:'Раздвижной фасад · направляющие',drop:'Откидной вниз · ограничитель'};
